/* ========================================
   CreativeHub — Global Styles
   ======================================== */

:root {
  --primary: #F02D00;
  --primary-hover: #d12600;
  --dark: #171717;
  --dark-secondary: #2a2a2a;
  --gray-100: #f5f5f5;
  --gray-200: #e5e5e5;
  --gray-300: #d4d4d4;
  --gray-400: #a3a3a3;
  --gray-500: #737373;
  --gray-600: #525252;
  --white: #FFFFFF;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --max-width: 1280px;
  --header-height: 64px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ========================================
   Typography
   ======================================== */

h1, h2, h3, h4 { font-weight: 700; line-height: 1.2; }

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.text-xl { font-size: 1.25rem; }
.text-2xl { font-size: 1.5rem; }
.text-3xl { font-size: 1.875rem; }
.text-4xl { font-size: 2.25rem; }

.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

/* ========================================
   Header
   ======================================== */

.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  height: var(--header-height);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--dark);
  transition: color 0.2s;
}

.nav-links a:hover { color: var(--primary); }

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.search-btn {
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  color: var(--gray-600);
  transition: background 0.2s;
}

.search-btn:hover { background: var(--gray-100); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}

.btn-primary:hover { background: var(--primary-hover); }

.btn-outline {
  border: 1.5px solid var(--dark);
  color: var(--dark);
  background: transparent;
}

.btn-outline:hover { background: var(--dark); color: var(--white); }

.btn-dark {
  background: var(--dark);
  color: var(--white);
}

.btn-dark:hover { background: var(--dark-secondary); }

.btn-lg { padding: 14px 28px; font-size: 1rem; }

.mobile-menu-btn { display: none; }

/* ========================================
   Promo Banner
   ======================================== */

.promo-banner {
  background: var(--dark);
  color: var(--white);
  padding: 10px 0;
  font-size: 0.875rem;
  position: relative;
}

.promo-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.promo-banner .badge {
  background: var(--primary);
  color: var(--white);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}

.promo-banner .close {
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 28px; height: 28px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--gray-400);
  transition: background 0.2s;
}

.promo-banner .close:hover { background: rgba(255,255,255,0.1); color: var(--white); }

/* ========================================
   Hero Carousel
   ======================================== */

.hero-section {
  background: var(--gray-100);
  padding: 48px 0 56px;
}

.hero-carousel {
  position: relative;
  overflow: hidden;
}

.hero-slide {
  display: none;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-slide.active { display: grid; }

.hero-content { max-width: 520px; }

.hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--primary);
  color: var(--white);
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.hero-desc {
  font-size: 1.0625rem;
  color: var(--gray-600);
  margin-bottom: 24px;
  line-height: 1.6;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.hero-meta span {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.875rem;
  color: var(--gray-500);
}

.hero-price {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}

.hero-price .original {
  font-size: 1.125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}

.hero-price .sale {
  font-size: 2rem;
  font-weight: 800;
  color: var(--primary);
}

.hero-price .discount {
  background: var(--dark);
  color: var(--white);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
}

.hero-image {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 16/10;
  background: var(--gray-200);
}

.hero-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  background: var(--white);
  color: var(--dark);
  padding: 6px 12px;
  border-radius: var(--radius-md);
  font-size: 0.75rem;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

.carousel-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.carousel-arrow {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  display: flex; align-items: center; justify-content: center;
  color: var(--dark);
  transition: all 0.2s;
}

.carousel-arrow:hover {
  background: var(--dark);
  border-color: var(--dark);
  color: var(--white);
}

.carousel-dots {
  display: flex;
  gap: 8px;
}

.carousel-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: all 0.2s;
}

.carousel-dot.active {
  background: var(--primary);
  width: 24px;
  border-radius: 5px;
}

/* ========================================
   Course Cards
   ======================================== */

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}

.section-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.section-link {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.section-link:hover { text-decoration: underline; }

.course-carousel-wrap {
  position: relative;
}

.course-carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding-bottom: 8px;
}

.course-carousel::-webkit-scrollbar { display: none; }

.course-card {
  flex: 0 0 280px;
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.2s;
}

.course-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.course-thumb {
  position: relative;
  aspect-ratio: 16/10;
  background: var(--gray-200);
  overflow: hidden;
}

.course-thumb img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.3s;
}

.course-card:hover .course-thumb img { transform: scale(1.03); }

.course-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--primary);
  color: var(--white);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
}

.course-info { padding: 14px; }

.course-title {
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-instructor {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: 10px;
}

.course-stats {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: 10px;
}

.course-stats span { display: flex; align-items: center; gap: 3px; }

.course-price {
  display: flex;
  align-items: center;
  gap: 8px;
}

.course-price .original {
  font-size: 0.8125rem;
  color: var(--gray-400);
  text-decoration: line-through;
}

.course-price .sale {
  font-size: 1rem;
  font-weight: 700;
  color: var(--primary);
}

.course-price .discount {
  background: var(--dark);
  color: var(--white);
  padding: 1px 6px;
  border-radius: 3px;
  font-size: 0.6875rem;
  font-weight: 700;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--white);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--dark);
  z-index: 10;
  transition: all 0.2s;
}

.carousel-btn:hover { background: var(--dark); color: var(--white); border-color: var(--dark); }

.carousel-btn.prev { left: -20px; }

.carousel-btn.next { right: -20px; }

/* ========================================
   Value Propositions
   ======================================== */

.value-section { padding: 64px 0; background: var(--white); }

.value-section .section-title { text-align: center; margin-bottom: 40px; }

.value-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.value-card {
  padding: 24px;
  border-radius: var(--radius-lg);
  background: var(--gray-100);
  transition: background 0.2s;
}

.value-card:hover { background: var(--gray-200); }

.value-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius-md);
  background: var(--primary);
  color: var(--white);
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 14px;
}

.value-card h3 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 6px;
}

.value-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  line-height: 1.55;
}

/* ========================================
   Footer
   ======================================== */

.footer {
  background: var(--dark);
  color: var(--white);
  padding: 56px 0 24px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 700;
  margin-bottom: 14px;
  color: var(--white);
}

.footer-col ul { list-style: none; }

.footer-col li { margin-bottom: 8px; }

.footer-col a {
  font-size: 0.8125rem;
  color: var(--gray-400);
  transition: color 0.2s;
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid var(--dark-secondary);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-brand {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--white);
}

.footer-apps {
  display: flex;
  gap: 10px;
}

.app-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--dark-secondary);
  color: var(--white);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  font-size: 0.75rem;
  font-weight: 600;
}

.footer-legal {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.footer-legal a {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.footer-legal a:hover { color: var(--white); }

.footer-lang {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.footer-lang a {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.footer-lang a:hover { color: var(--white); }

.footer-accordion-toggle {
  display: none;
}

/* ========================================
   Courses Page
   ======================================== */

.courses-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 32px;
  padding: 32px 0 56px;
}

.sidebar {
  position: sticky;
  top: calc(var(--header-height) + 16px);
  align-self: start;
}

.sidebar-section { margin-bottom: 28px; }

.sidebar-title {
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 12px;
  color: var(--gray-500);
}

.sidebar-list { list-style: none; }

.sidebar-list li { margin-bottom: 6px; }

.sidebar-list a {
  display: block;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  color: var(--gray-600);
  transition: all 0.15s;
}

.sidebar-list a:hover,
.sidebar-list a.active {
  background: var(--gray-100);
  color: var(--dark);
  font-weight: 600;
}

.courses-main h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 24px;
}

.category-row { margin-bottom: 40px; }

.category-row h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}

/* ========================================
   Projects Page
   ======================================== */

.projects-header {
  padding: 32px 0 20px;
}

.projects-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 20px;
}

.project-filters {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.filter-select {
  padding: 8px 14px;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-300);
  font-size: 0.875rem;
  background: var(--white);
  color: var(--dark);
  min-width: 160px;
}

.filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.filter-pill {
  padding: 6px 14px;
  border-radius: 20px;
  border: 1px solid var(--gray-300);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--gray-600);
  background: var(--white);
  transition: all 0.15s;
}

.filter-pill:hover,
.filter-pill.active {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.masonry-grid {
  column-count: 4;
  column-gap: 16px;
  padding-bottom: 40px;
}

.project-card {
  break-inside: avoid;
  margin-bottom: 16px;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s;
}

.project-card:hover { box-shadow: var(--shadow-lg); }

.project-thumb {
  position: relative;
  background: var(--gray-200);
}

.project-thumb img { width: 100%; display: block; }

.project-winner {
  position: absolute;
  top: 10px;
  left: 10px;
  background: gold;
  color: var(--dark);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 0.6875rem;
  font-weight: 700;
}

.project-info { padding: 12px; }

.project-title {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.project-author {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-bottom: 8px;
}

.project-stats {
  display: flex;
  gap: 12px;
  font-size: 0.75rem;
  color: var(--gray-500);
}

.project-stats span { display: flex; align-items: center; gap: 3px; }

/* ========================================
   Plus Page
   ======================================== */

.plus-hero {
  background: var(--dark);
  color: var(--white);
  padding: 64px 0;
  text-align: center;
}

.plus-hero h1 {
  font-size: 2.75rem;
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.plus-hero p {
  font-size: 1.125rem;
  color: var(--gray-400);
  max-width: 560px;
  margin: 0 auto 32px;
}

.pricing-section { padding: 48px 0; background: var(--gray-100); }

.pricing-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 32px;
}

.pricing-tab {
  padding: 10px 24px;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 600;
  background: var(--white);
  color: var(--gray-600);
  border: 1.5px solid var(--gray-300);
  transition: all 0.2s;
}

.pricing-tab.active {
  background: var(--dark);
  color: var(--white);
  border-color: var(--dark);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 720px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  border: 2px solid transparent;
  transition: border-color 0.2s;
}

.pricing-card.featured { border-color: var(--primary); position: relative; }

.pricing-card .badge-popular {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 14px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-card h3 {
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 4px;
}

.pricing-card .billed {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 16px;
}

.pricing-card .savings {
  display: inline-block;
  background: #e6f9ed;
  color: #16a34a;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  margin-bottom: 20px;
}

.pricing-card ul { list-style: none; margin-bottom: 24px; }

.pricing-card li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: 10px;
}

.pricing-card li i { color: var(--primary); }

.pricing-terms {
  text-align: center;
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-top: 20px;
}

.benefits-section { padding: 56px 0; }

.benefits-section .section-title { text-align: center; margin-bottom: 40px; }

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.benefit-card {
  padding: 28px;
  border-radius: var(--radius-lg);
  background: var(--gray-100);
  text-align: center;
}

.benefit-icon {
  width: 52px; height: 52px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px;
}

.benefit-card h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.benefit-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  line-height: 1.55;
}

.faq-section { padding: 56px 0; background: var(--gray-100); }

.faq-section .section-title { text-align: center; margin-bottom: 32px; }

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  background: var(--white);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  font-size: 1rem;
  font-weight: 600;
  text-align: left;
  background: none;
  border: none;
  cursor: pointer;
}

.faq-question i { transition: transform 0.2s; color: var(--gray-500); }

.faq-item.open .faq-question i { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.open .faq-answer { max-height: 300px; }

.faq-answer-inner {
  padding: 0 20px 18px;
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.6;
}

.cert-section {
  padding: 56px 0;
  text-align: center;
}

.cert-section h2 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.cert-section p {
  font-size: 1rem;
  color: var(--gray-600);
  max-width: 520px;
  margin: 0 auto 32px;
}

.cert-mockup {
  max-width: 640px;
  margin: 0 auto;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  background: var(--gray-100);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400);
  font-size: 1rem;
}

/* ========================================
   Login Page
   ======================================== */

.login-page {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.login-visual {
  background: var(--dark);
  color: var(--white);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
  position: relative;
  overflow: hidden;
}

.login-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(240,45,0,0.15) 0%, transparent 60%);
}

.login-visual-content { position: relative; z-index: 1; max-width: 420px; }

.login-visual h2 {
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.login-visual p {
  font-size: 1.0625rem;
  color: var(--gray-400);
  line-height: 1.6;
}

.login-form-wrap {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px;
  max-width: 480px;
  margin: 0 auto;
  width: 100%;
}

.login-form-wrap h1 {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.login-form-wrap .subtitle {
  font-size: 0.9375rem;
  color: var(--gray-500);
  margin-bottom: 28px;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px;
  border-radius: var(--radius-md);
  border: 1.5px solid var(--gray-300);
  font-size: 0.9375rem;
  font-weight: 600;
  background: var(--white);
  color: var(--dark);
  transition: background 0.2s;
}

.social-btn:hover { background: var(--gray-100); }

.divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  font-size: 0.8125rem;
  color: var(--gray-500);
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--gray-200);
}

.form-group { margin-bottom: 16px; }

.form-group label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--dark);
}

.form-group input {
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--radius-md);
  border: 1.5px solid var(--gray-300);
  font-size: 0.9375rem;
  transition: border-color 0.2s;
}

.form-group input:focus {
  outline: none;
  border-color: var(--primary);
}

.password-wrap { position: relative; }

.password-wrap input { padding-right: 44px; }

.password-toggle {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-500);
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
}

.password-toggle:hover { background: var(--gray-100); }

.form-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.form-actions a {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--primary);
}

.form-actions a:hover { text-decoration: underline; }

.btn-full { width: 100%; }

.login-footer {
  text-align: center;
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 20px;
}

.login-footer a {
  font-weight: 600;
  color: var(--primary);
}

/* ========================================
   Responsive
   ======================================== */

@media (max-width: 1024px) {
  .value-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: repeat(2, 1fr); }
  .masonry-grid { column-count: 3; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-actions .btn-outline { display: none; }
  .mobile-menu-btn { display: flex; }

  .hero-slide { grid-template-columns: 1fr; }
  .hero-slide.active { display: flex; flex-direction: column-reverse; }
  .hero-title { font-size: 1.875rem; }

  .value-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .masonry-grid { column-count: 2; }
  .pricing-cards { grid-template-columns: 1fr; }

  .courses-layout { grid-template-columns: 1fr; }
  .sidebar { position: static; margin-bottom: 24px; }

  .login-page { grid-template-columns: 1fr; }
  .login-visual { display: none; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; margin-bottom: 24px; }

  .footer-col {
    border-bottom: 1px solid var(--dark-secondary);
  }

  .footer-col h4 {
    padding: 14px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-col.open ul { max-height: 600px; }

  .footer-col h4::after {
    content: '+';
    font-size: 1.25rem;
    font-weight: 400;
    transition: transform 0.2s;
  }

  .footer-col.open h4::after { transform: rotate(45deg); }

  .footer-col li { padding: 6px 0; }
  .footer-col li:last-child { margin-bottom: 14px; }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .carousel-btn.prev { left: 8px; }
  .carousel-btn.next { right: 8px; }
}

@media (max-width: 480px) {
  .masonry-grid { column-count: 1; }
  .course-grid { grid-template-columns: 1fr; }
  .hero-title { font-size: 1.5rem; }
  .plus-hero h1 { font-size: 2rem; }
}

/* ========================================
   CreativeHub — Shared JavaScript
   ======================================== */

// Promo banner dismiss
function initPromoBanner() {
  const banner = document.getElementById('promo-banner');
  const closeBtn = document.getElementById('promo-close');
  if (!banner || !closeBtn) return;
  closeBtn.addEventListener('click', () => {
    banner.style.display = 'none';
  });
}

// Countdown timer
function initCountdown() {
  const el = document.getElementById('countdown');
  if (!el) return;
  let hours = 5, minutes = 42, seconds = 18;
  setInterval(() => {
    seconds--;
    if (seconds < 0) { seconds = 59; minutes--; }
    if (minutes < 0) { minutes = 59; hours--; }
    if (hours < 0) { hours = 23; }
    el.textContent = `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`;
  }, 1000);
}

// Hero carousel
function initHeroCarousel() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.carousel-dot');
  const prevBtn = document.getElementById('hero-prev');
  const nextBtn = document.getElementById('hero-next');
  if (!slides.length) return;

  let current = 0;

  function showSlide(idx) {
    slides.forEach((s, i) => {
      s.classList.toggle('active', i === idx);
    });
    dots.forEach((d, i) => {
      d.classList.toggle('active', i === idx);
    });
    current = idx;
  }

  if (prevBtn) prevBtn.addEventListener('click', () => {
    showSlide((current - 1 + slides.length) % slides.length);
  });
  if (nextBtn) nextBtn.addEventListener('click', () => {
    showSlide((current + 1) % slides.length);
  });
  dots.forEach((d, i) => {
    d.addEventListener('click', () => showSlide(i));
  });

  // Auto-advance
  setInterval(() => {
    showSlide((current + 1) % slides.length);
  }, 6000);
}

// Course carousel scroll
function initCourseCarousels() {
  document.querySelectorAll('[data-carousel]').forEach(wrapper => {
    const track = wrapper.querySelector('.course-carousel');
    const prev = wrapper.querySelector('.carousel-btn.prev');
    const next = wrapper.querySelector('.carousel-btn.next');
    if (!track) return;

    const scrollAmount = 300;
    if (prev) prev.addEventListener('click', () => {
      track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });
    if (next) next.addEventListener('click', () => {
      track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });
  });
}

// Footer accordion (mobile)
function initFooterAccordion() {
  if (window.innerWidth > 768) return;
  document.querySelectorAll('.footer-col h4').forEach(title => {
    title.addEventListener('click', () => {
      title.parentElement.classList.toggle('open');
    });
  });
}

// Plus pricing toggle
function initPricingToggle() {
  const yearlyBtn = document.getElementById('tab-yearly');
  const monthlyBtn = document.getElementById('tab-monthly');
  const yearlyCard = document.getElementById('card-yearly');
  const monthlyCard = document.getElementById('card-monthly');
  if (!yearlyBtn || !monthlyBtn) return;

  yearlyBtn.addEventListener('click', () => {
    yearlyBtn.classList.add('active');
    monthlyBtn.classList.remove('active');
    if (yearlyCard) yearlyCard.style.display = 'block';
    if (monthlyCard) monthlyCard.style.display = 'block';
  });

  monthlyBtn.addEventListener('click', () => {
    monthlyBtn.classList.add('active');
    yearlyBtn.classList.remove('active');
    if (yearlyCard) yearlyCard.style.display = 'block';
    if (monthlyCard) monthlyCard.style.display = 'block';
  });
}

// FAQ accordion
function initFaqAccordion() {
  document.querySelectorAll('.faq-question').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const isOpen = item.classList.contains('open');
      document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
      if (!isOpen) item.classList.add('open');
    });
  });
}

// Password toggle
function initPasswordToggle() {
  const toggle = document.getElementById('password-toggle');
  const input = document.getElementById('password');
  if (!toggle || !input) return;
  toggle.addEventListener('click', () => {
    const type = input.getAttribute('type') === 'password' ? 'text' : 'password';
    input.setAttribute('type', type);
    toggle.querySelector('i').className = type === 'password' ? 'ri-eye-line' : 'ri-eye-off-line';
  });
}

// Courses sidebar filter
function initCourseFilter() {
  const links = document.querySelectorAll('.sidebar-list a');
  const cards = document.querySelectorAll('.course-card[data-category]');
  if (!links.length || !cards.length) return;

  links.forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      links.forEach(l => l.classList.remove('active'));
      link.classList.add('active');
      const cat = link.dataset.filter;
      cards.forEach(card => {
        if (!cat || cat === 'all' || card.dataset.category === cat) {
          card.style.display = '';
        } else {
          card.style.display = 'none';
        }
      });
    });
  });
}

// Projects sort/filter
function initProjectFilters() {
  const sortSelect = document.getElementById('project-sort');
  const timeSelect = document.getElementById('project-time');
  const fieldPills = document.querySelectorAll('.filter-pill[data-field]');
  const cards = document.querySelectorAll('.project-card');

  function applyFilters() {
    const sort = sortSelect ? sortSelect.value : 'featured';
    const time = timeSelect ? timeSelect.value : 'all';
    const activeField = document.querySelector('.filter-pill.active');
    const field = activeField ? activeField.dataset.field : 'all';

    const arr = Array.from(cards);
    arr.forEach(card => {
      let show = true;
      if (field !== 'all' && card.dataset.field !== field) show = false;
      if (time !== 'all' && card.dataset.time !== time) show = false;
      card.style.display = show ? '' : 'none';
    });

    // Simple sort by data attribute
    const grid = document.querySelector('.masonry-grid');
    if (!grid) return;
    const visible = arr.filter(c => c.style.display !== 'none');
    visible.sort((a, b) => {
      if (sort === 'most-liked') return parseInt(b.dataset.likes) - parseInt(a.dataset.likes);
      if (sort === 'most-viewed') return parseInt(b.dataset.views) - parseInt(a.dataset.views);
      if (sort === 'most-recent') return parseInt(b.dataset.timeOrder) - parseInt(a.dataset.timeOrder);
      return 0;
    });
    visible.forEach(c => grid.appendChild(c));
  }

  if (sortSelect) sortSelect.addEventListener('change', applyFilters);
  if (timeSelect) timeSelect.addEventListener('change', applyFilters);
  fieldPills.forEach(pill => {
    pill.addEventListener('click', () => {
      fieldPills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      applyFilters();
    });
  });
}

// Mobile menu
function initMobileMenu() {
  const btn = document.getElementById('mobile-menu-btn');
  const nav = document.getElementById('mobile-nav');
  if (!btn || !nav) return;
  btn.addEventListener('click', () => {
    nav.classList.toggle('open');
  });
}

// Initialize everything
document.addEventListener('DOMContentLoaded', () => {
  initPromoBanner();
  initCountdown();
  initHeroCarousel();
  initCourseCarousels();
  initFooterAccordion();
  initPricingToggle();
  initFaqAccordion();
  initPasswordToggle();
  initCourseFilter();
  initProjectFilters();
  initMobileMenu();
});

